import React from 'react';
import { FaCalendarAlt, FaExternalLinkAlt } from 'react-icons/fa';
import { SiHuggingface } from 'react-icons/si';
import warfarin from '../assets/images/Warfarin_Img.png';
import bworks from '../assets/images/Bworks.jpeg';
import security from '../assets/images/SecuritySurveillance_Img.jpeg';

const Projects = () => {
  const projects = [
    {
      title: "Warfarin Dosage Prediction Using Machine Learning",
      date: "Aug 2024 – Dec 2024",
      description: "Developed predictive ML models to optimize warfarin dosage, enhancing precision and patient safety in clinical settings.",
      tech: ["Python", "Machine Learning", "Logistic Regression", "Random Forest", "SVM", "MLP", "Gradio", "Hugging Face"],
      image: warfarin,
      links: [
        {
          name: "Hugging Face",
          url: "https://huggingface.co/spaces/bkrishnakanth/warfarin-prediction",
          icon: <SiHuggingface />
        }
      ]
    },
    {
      title: "BWorks - Material Donor Mutual Assist",
      date: "Jan 2024 – May 2024",
      description: "Created a MERN stack donor engagement system to streamline communication and track donations from initiation to end-use.",
      tech: ["MongoDB", "Express", "React", "Node.js", "Amazon SES", "JavaScript"],
      image: bworks,
      links: []
    },
    {
      title: "Security Surveillance Monitoring System",
      date: "Mar 2022 – June 2022",
      description: "Developed a surveillance system with motion detection and face recognition features using Python, Tkinter, and OpenCV.",
      tech: ["Python", "Tkinter", "OpenCV", "NumPy", "SciPy"],
      image: security,
      links: []
    }
  ];
  
  return (
    <section id="projects" className="py-5" style={{background: 'var(--section-bg-light, #f8f9fa)'}}>
      <div className="container py-5">
        <h2 
          className="text-center mb-5 position-relative display-5"
          data-aos="fade-up"
          style={{color: 'var(--text-color, #333)'}}
        >
          Projects
          <div className="position-absolute start-50 translate-middle-x mt-3" style={{width: '80px', height: '4px', background: '#4285f4', bottom: '-10px'}}></div>
        </h2>
        
        <div className="row">
          {projects.map((project, index) => (
            <div 
              className="col-lg-4 col-md-6 mb-4" 
              key={index}
              data-aos="fade-up"
              data-aos-delay={index * 100}
            >
              <div className="card h-100 shadow-sm" style={{background: 'var(--card-bg, white)', borderColor: 'var(--border-color, #dee2e6)'}}>
                <div 
                  style={{height: '180px', overflow: 'hidden'}}
                  data-aos="zoom-in"
                  data-aos-delay={index * 150}
                >
                  <img 
                    src={project.image} 
                    alt={project.title} 
                    className="card-img-top h-100" 
                    style={{objectFit: 'cover', transition: 'transform 0.5s ease'}} 
                  />
                </div>
                
                <div className="card-body">
                  <h5 className="card-title fw-bold" style={{color: 'var(--text-color, #333)'}}>{project.title}</h5>
                  <div className="d-flex align-items-center mb-3 text-muted small">
                    <FaCalendarAlt className="me-2" />
                    {project.date}
                  </div>
                  <p className="card-text" style={{color: 'var(--text-color, #333)'}}>{project.description}</p>
                  
                  <div className="d-flex flex-wrap mb-3">
                    {project.tech.map((tech, i) => (
                      <span 
                        key={i} 
                        className="badge me-2 mb-2 px-3 py-2 rounded-pill"
                        style={{
                          background: 'var(--skill-tag-bg, #e9ecef)', 
                          color: 'var(--skill-tag-text, #495057)'
                        }}
                      >
                        {tech}
                      </span>
                    ))}
                  </div>
                  
                  {project.links && project.links.length > 0 && (
                    <div className="mt-4">
                      {project.links.map((link, i) => (
                        <a 
                          key={i}
                          href={link.url} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="d-inline-flex align-items-center text-decoration-none"
                          style={{
                            background: 'linear-gradient(135deg, #FFD21E 0%, #FF9A0E 100%)',
                            color: '#000',
                            padding: '0.5rem 1.25rem',
                            borderRadius: '30px',
                            fontWeight: '500',
                            boxShadow: '0 4px 10px rgba(255, 154, 14, 0.3)',
                            transition: 'all 0.3s ease',
                          }}
                          onMouseOver={(e) => e.currentTarget.style.transform = 'translateY(-3px)'}
                          onMouseOut={(e) => e.currentTarget.style.transform = 'translateY(0)'}
                        >
                          <span style={{ fontSize: '1.25rem', marginRight: '0.5rem' }}>
                            {link.icon}
                          </span>
                          {link.name}
                          <FaExternalLinkAlt className="ms-2" size={12} />
                        </a>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Projects;